<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ElButton, ElDialog, ElInput, ElMessage, ElTag } from 'element-plus'
import { ArrowLeft, ClipboardList, Download, FileText, MessageCircle, ReceiptText, Upload } from 'lucide-vue-next'
import { dateText, money, STATUS_LABEL, useCommerceStore, type OrderStatus } from '@/stores/commerce'

const c = useCommerceStore()
const router = useRouter()
const route = useRoute()
const order = computed(() => c.data.orders.find(item => item.id === route.params.id))
const fromAfterSale = computed(() => route.query.from === 'aftersale')
const latestRefund = computed(() => order.value ? c.data.refunds.find(item => item.orderId === order.value!.id) : undefined)
const activeRefund = computed(() => order.value ? c.activeRefund(order.value.id) : undefined)
const invoices = computed(() => order.value ? c.data.invoices.filter(item => item.kind === 'customer' && item.orderIds.includes(order.value!.id)) : [])
const issuedAmount = computed(() => invoices.value.filter(item => item.status === 'issued').reduce((sum, item) => sum + (item.amounts?.[order.value!.id] ?? item.amount / item.orderIds.length), 0))
const spec = computed(() => { if (order.value?.specSnapshot) return order.value.specSnapshot; const service = c.data.services.find(item => item.id === order.value?.serviceId); return service?.specs.find(item => item.price === order.value?.amount) || service?.specs[0] })
const parkName = computed(() => c.data.parks.find(item => item.id === order.value?.parkId)?.name || '—')
const tabs = [['bill', '账单明细'], ['contract', '合同协议'], ['delivery', '履约验收'], ['settlement', '结算与评价'], ['service', '服务详情']] as const
const defaultTab = (status?: OrderStatus) => status === 'pending_contract' ? 'contract' : status === 'in_service' || status === 'pending_acceptance' ? 'delivery' : status === 'completed' ? 'settlement' : 'bill'
const tab = ref(String(route.query.tab || (activeRefund.value ? 'bill' : defaultTab(order.value?.status))))
watch(() => order.value?.status, (next, prev) => { if (next && prev && next !== prev) tab.value = defaultTab(next) })
watch(() => route.query.tab, value => { if (typeof value === 'string' && tabs.some(([key]) => key === value)) tab.value = value })
const contactOpen = ref(false)
const files = ref<string[]>([])
const note = ref('')
const canInvoice = computed(() => !!order.value && order.value.paid - order.value.refunded > 0 && !activeRefund.value && c.invoiceable(order.value) > 0)
const canDeliver = computed(() => order.value?.status === 'in_service' && order.value.contractState === 'confirmed' && !!order.value.paid && !activeRefund.value)
const statusMessage = computed(() => {
  if (activeRefund.value) return '客户退款申请处理中。合同、履约及新开票操作已暂停，请先处理售后。'
  switch (order.value?.status) {
    case 'pending_payment': return '等待客户支付；下单后 7 天未支付，订单将自动取消。'
    case 'pending_contract': return order.value.contractState === 'waiting' ? '合同已上传，等待客户确认。' : order.value.contractState === 'rejected' ? '客户已驳回合同，请重新上传双方签署的扫描件。' : '客户已支付，请下载模板并上传双方签署的合同。'
    case 'in_service': return '合同已确认，请上传交付物并申请客户验收。'
    case 'pending_acceptance': return '已申请验收，等待客户处理；申请后 7 个自然日未处理将自动通过。'
    case 'completed': return order.value.settlement === 'settled' ? '订单已完成，款项已结算。' : '订单已完成，售后期结束且无未完成退款后进入结算。'
    case 'cancelled': return '订单已取消，合同与履约操作不可用。'
    default: return ''
  }
})
const progressIndex = computed(() => order.value?.status === 'cancelled' ? order.value.acceptanceAt ? 3 : order.value.contractState === 'confirmed' ? 2 : order.value.paid ? 1 : 0 : ({ pending_payment: 0, pending_contract: 1, in_service: 2, pending_acceptance: 3, completed: 4 })[order.value?.status || 'pending_payment'])
const steps = ['支付', '签约', '交付', '验收', '完成']
function addDays(value: string | undefined, days: number, workdays = false) {
  if (!value) return ''
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return ''
  let left = days
  while (left > 0) { date.setDate(date.getDate() + 1); if (!workdays || date.getDay() !== 0 && date.getDay() !== 6) left-- }
  return date.toISOString()
}
const progressDates = computed(() => {
  const o = order.value
  if (!o) return []
  const start = addDays(o.paymentAt, spec.value?.startDays || 0, spec.value?.dayType === '工作日')
  const delivery = addDays(o.contractConfirmedAt || start, spec.value?.deliveryDays || 0)
  return [
    { plan: addDays(o.createdAt, 7), actual: o.paymentAt },
    { plan: start, actual: o.contractConfirmedAt },
    { plan: delivery, actual: o.acceptanceAt },
    { plan: addDays(o.acceptanceAt, 7), actual: o.completedAt },
    { plan: '', actual: o.completedAt },
  ]
})
const shortDate = (value?: string) => value ? dateText(value).slice(0, 10) : ''
const settlementBase = computed(() => Math.max(0, (order.value?.paid || 0) - (order.value?.refunded || 0)))
const platformFee = computed(() => settlementBase.value * (order.value?.shareRate || 0) / 100)
function selectTab(value: string) { tab.value = value; router.replace({ query: { ...route.query, tab: value } }) }
function back() { router.push(fromAfterSale.value ? { path: '/aftersale', query: { order: route.params.id } } : '/order') }
function goAfterSale(action: 'view' | 'process' = 'view') { if (order.value) router.push({ path: '/aftersale', query: { order: order.value.id, ...(latestRefund.value ? { refund: latestRefund.value.id, action } : {}) } }) }
function goInvoice() { if (order.value && canInvoice.value) router.push({ path: '/invoice/open', query: { order: order.value.id } }) }
function pick(event: Event, kind: 'contract' | 'delivery') {
  const list = Array.from((event.target as HTMLInputElement).files || [])
  const allowed = /\.(pdf|png|jpe?g|docx?)$/i
  if (list.some(file => !allowed.test(file.name))) { ElMessage.error('仅支持 PDF、图片和 Word 文件'); return }
  if (kind === 'contract' && list[0] && order.value) {
    if (c.submitContract(order.value.id, list[0].name)) ElMessage.success('合同已上传，等待客户确认')
    else ElMessage.warning('当前状态不能上传合同')
  } else files.value = list.map(file => file.name)
  ;(event.target as HTMLInputElement).value = ''
}
function deliver() {
  if (!order.value) return
  if (c.requestAcceptance(order.value.id, files.value, note.value)) { ElMessage.success('已提交客户验收'); files.value = []; note.value = '' }
  else ElMessage.warning('请上传交付文件，并确认合同已通过且没有进行中的退款')
}
function downloadTemplate() {
  const content = `服务合同模板（演示）\n订单号：${order.value?.id || ''}\n服务：${order.value?.serviceName || ''}\n请线下核对双方主体、服务范围、交付标准及签章。`
  const link = document.createElement('a')
  link.href = URL.createObjectURL(new Blob([content], { type: 'text/plain;charset=utf-8' }))
  link.download = `合同模板-${order.value?.id || '订单'}.txt`
  link.click()
  URL.revokeObjectURL(link.href)
}
</script>

<template>
  <div v-if="order" class="biz-page order-detail-page">
    <header class="order-head">
      <button class="back-link" type="button" @click="back"><ArrowLeft :size="15" />{{ fromAfterSale ? '返回售后管理' : '返回订单管理' }}</button>
      <div class="order-title-row"><span class="head-icon"><ClipboardList :size="23" /></span><div><h1>订单详情</h1><p>订单号 {{ order.id }} <span>·</span> 下单 {{ dateText(order.createdAt) }}</p></div><ElTag :type="order.status === 'completed' ? 'success' : order.status === 'cancelled' ? 'info' : 'primary'" effect="light">{{ STATUS_LABEL[order.status] }}</ElTag></div>
    </header>

    <div class="status-banner" :class="{ danger: activeRefund, muted: order.status === 'cancelled' }"><div><strong>{{ activeRefund ? '售后处理中' : STATUS_LABEL[order.status] }}</strong><span>{{ statusMessage }}</span></div><ElButton v-if="activeRefund" type="danger" size="small" @click="goAfterSale('process')">处理退款</ElButton><ElButton v-else-if="canInvoice && order.status !== 'pending_payment'" type="primary" size="small" @click="goInvoice">上传发票</ElButton></div>

    <section class="progress-panel" aria-label="订单进度"><div class="panel-kicker">订单进度</div><div class="progress-track"><div v-for="(step, index) in steps" :key="step" class="progress-step" :class="{ done: progressIndex > index, current: progressIndex === index && order.status !== 'cancelled', stopped: order.status === 'cancelled' }"><span class="step-dot">{{ progressIndex > index ? '✓' : index + 1 }}</span><strong>{{ step }}</strong><small v-if="index === 0">{{ order.paid > 0 ? '已支付' : order.status === 'cancelled' ? '已终止' : '待支付' }}</small><small v-else-if="index === 1">{{ order.contractState === 'confirmed' ? '客户已确认' : order.contractState === 'waiting' ? '待客户确认' : order.contractState === 'rejected' ? '客户已驳回' : '待签约' }}</small><small v-else-if="index === 2">{{ order.deliverables.length || order.status === 'completed' ? '已交付' : '待交付' }}</small><small v-else-if="index === 3">{{ order.status === 'completed' ? '已通过' : order.status === 'pending_acceptance' ? '待客户验收' : '待申请' }}</small><small v-else>{{ order.status === 'completed' ? '已完成' : '—' }}</small><small v-if="progressDates[index]?.plan || progressDates[index]?.actual" class="step-time"><span v-if="progressDates[index]?.plan">计划 {{ shortDate(progressDates[index]?.plan) }}</span><span v-if="progressDates[index]?.actual">完成 {{ shortDate(progressDates[index]?.actual) }}</span></small></div></div><p v-if="order.status === 'cancelled'" class="progress-cancelled">主履约链已终止；有剩余实付的订单仍按售后期规则结算。</p></section>

    <div class="detail-layout"><main class="detail-main"><nav class="detail-tabs" aria-label="订单详情栏目"><button v-for="[key, label] in tabs" :key="key" type="button" :class="{ active: tab === key }" @click="selectTab(key)">{{ label }}</button></nav>
      <section v-if="tab === 'bill'" class="detail-panel"><div class="section-title"><span class="section-icon"><ReceiptText :size="17" /></span><h2>账单明细</h2></div><h3>收付款</h3><div class="data-table-wrap"><table class="detail-table"><thead><tr><th>阶段</th><th>应付金额</th><th>实付金额</th><th>支付方式</th><th>支付时间</th><th>状态</th></tr></thead><tbody><tr><td>一次性付款</td><td class="numeric">{{ money(order.amount) }}</td><td class="numeric strong">{{ money(order.paid) }}</td><td>—</td><td>{{ dateText(order.paymentAt) }}</td><td><ElTag :type="order.paid ? 'success' : 'info'" size="small" effect="plain">{{ order.paid ? '已支付' : '待支付' }}</ElTag></td></tr></tbody></table></div><div class="bill-totals"><div><span>订单金额</span><strong>{{ money(order.amount) }}</strong></div><div><span>已付金额</span><strong>{{ money(order.paid) }}</strong></div><div><span>待付金额</span><strong>{{ money(Math.max(0, order.amount - order.paid)) }}</strong></div><div><span>已退款</span><strong>{{ money(order.refunded) }}</strong></div></div>
        <div class="subsection-head"><h3>退款信息</h3><ElButton v-if="latestRefund" text type="primary" @click="goAfterSale('view')">查看退款详情</ElButton></div><div v-if="latestRefund" class="refund-card"><div class="refund-top"><strong>{{ latestRefund.reason || '退款申请' }}</strong><ElTag :type="latestRefund.status === 'refunded' ? 'success' : latestRefund.status === 'cancelled' ? 'info' : 'danger'" effect="light">{{ STATUS_LABEL[latestRefund.status] }}</ElTag></div><div class="refund-facts"><span>申请 {{ dateText(latestRefund.createdAt) }}</span><span>申请退款 {{ money(latestRefund.requested) }}</span><span>确认金额 {{ money(latestRefund.agreed) }}</span><span>{{ latestRefund.decision === 'close' ? '关闭订单' : '继续履约' }}</span></div><p v-if="latestRefund.note">{{ latestRefund.note }}</p></div><p v-else class="empty-line">暂无退款记录</p>
        <div class="subsection-head"><h3>对客发票</h3><ElButton v-if="canInvoice" type="primary" plain size="small" @click="goInvoice"><Upload :size="14" />上传发票</ElButton></div><div class="invoice-facts"><div><span>可开票金额</span><strong>{{ money(c.invoiceable(order)) }}</strong></div><div><span>已开票金额</span><strong>{{ money(issuedAmount) }}</strong></div><div><span>发票状态</span><strong>{{ invoices.some(item => item.status === 'issued') ? '已开具' : '未开票' }}</strong></div></div><div v-if="invoices.length" class="file-row"><FileText :size="16" /><span>{{ invoices[0].number }} · {{ invoices[0].file }}</span><ElButton text type="primary" @click="router.push('/invoice/record')">查看记录与退票</ElButton></div><p v-else class="empty-line">{{ activeRefund ? '退款处理中，暂不可新开票。' : '暂无发票记录' }}</p>
      </section>

      <section v-else-if="tab === 'contract'" class="detail-panel"><div class="section-title"><span class="section-icon"><FileText :size="17" /></span><h2>合同协议</h2></div><div class="state-strip"><strong>{{ ({ none: '待上传合同', waiting: '等待客户确认', rejected: '客户已驳回合同', confirmed: '合同已确认' })[order.contractState] }}</strong><span>{{ order.contractState === 'waiting' ? '客户将在客户端确认或驳回已上传的扫描件。' : order.contractState === 'rejected' ? '请核对客户反馈后重新上传。' : order.contractState === 'confirmed' ? '合同确认后进入服务中。' : '请核对合同模板，线下签署后上传扫描件。' }}</span></div><div class="contract-template"><FileText :size="22" /><div><strong>合同模板（演示）</strong><small>正式标准合同模板待业务文件接入；请线下核对主体与条款。</small></div><ElButton size="small" @click="downloadTemplate"><Download :size="14" />下载演示模板</ElButton></div><h3>签署文件</h3><div class="file-row"><FileText :size="16" /><span>{{ order.contractFile || '尚未上传双方签署的合同' }}</span></div><div v-if="order.status === 'pending_contract' && ['none', 'rejected'].includes(order.contractState) && !activeRefund" class="contract-upload"><label class="upload-action"><Upload :size="15" />{{ order.contractState === 'rejected' ? '重新上传合同' : '上传已签扫描件' }}<input type="file" accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" @change="pick($event, 'contract')" /></label><small>支持 PDF、图片和 Word。上传后等待客户确认。</small></div><p v-if="order.status === 'pending_payment'" class="context-note">客户支付后才能上传合同。</p><p v-if="activeRefund" class="context-note blocked">进行中退款已暂停合同操作。</p><h3 class="spaced">签约记录</h3><div class="record-list"><div><span class="record-mark"></span><strong>订单创建</strong><time>{{ dateText(order.createdAt) }}</time></div><div v-if="order.contractFile"><span class="record-mark"></span><strong>合同扫描件已上传</strong><time>{{ dateText(order.contractUploadedAt) }}</time></div><div v-if="order.contractState === 'confirmed' || order.contractState === 'rejected'"><span class="record-mark"></span><strong>{{ order.contractState === 'confirmed' ? '客户确认合同' : '客户驳回合同' }}</strong><time>{{ dateText(order.contractConfirmedAt) }}</time></div></div></section>

      <section v-else-if="tab === 'delivery'" class="detail-panel"><div class="section-title"><span class="section-icon"><Upload :size="17" /></span><h2>履约验收</h2></div><div class="delivery-summary"><div><span>交付周期</span><strong>{{ spec?.deliveryDays ? `${spec.deliveryDays} 天` : '—' }}</strong></div><div><span>交付标准</span><strong>{{ spec?.standard || '—' }}</strong></div><div><span>验收状态</span><strong>{{ order.status === 'completed' ? '已通过' : order.status === 'pending_acceptance' ? '待客户验收' : order.status === 'in_service' ? '待申请' : '未开始' }}</strong></div></div><h3>交付记录</h3><div class="file-row"><FileText :size="16" /><span>{{ order.deliverables.length ? order.deliverables.join('、') : '尚未提交交付物' }}</span></div><div v-if="order.deliveryNote" class="delivery-note"><span>交付说明</span><p>{{ order.deliveryNote }}</p></div><div v-if="order.acceptanceAt" class="context-note">申请验收 {{ dateText(order.acceptanceAt) }}；客户 7 个自然日未处理将自动通过。驳回后可重新提交，以新申请时间重新计时。</div><div v-if="canDeliver" class="delivery-form"><h3>提交交付物并申请验收</h3><label class="upload-action"><Upload :size="15" />选择交付文件<input type="file" multiple accept=".pdf,.png,.jpg,.jpeg,.doc,.docx" @change="pick($event, 'delivery')" /></label><small>{{ files.length ? files.join('、') : '支持 PDF、图片和 Word；至少上传一个文件。' }}</small><label class="field-label">交付说明<ElInput v-model="note" type="textarea" :rows="4" maxlength="1000" show-word-limit placeholder="说明已完成的工作和本次交付内容" /></label><ElButton type="primary" :disabled="!files.length" @click="deliver">申请客户验收</ElButton></div><p v-else-if="activeRefund" class="context-note blocked">进行中退款已暂停履约及验收操作。</p><p v-else-if="order.status === 'pending_acceptance'" class="context-note">已提交客户验收，等待客户通过或驳回。</p></section>

      <section v-else-if="tab === 'settlement'" class="detail-panel"><div class="section-title"><span class="section-icon"><ReceiptText :size="17" /></span><h2>结算与评价</h2></div><div class="settlement-hero"><div><span>预计供应商到账</span><strong>{{ money(Math.max(0, settlementBase - platformFee)) }}</strong><small>基于当前剩余实付和订单提点快照测算</small></div><ElTag :type="order.settlement === 'settled' ? 'success' : 'warning'" effect="light">{{ order.settlement === 'settled' ? '已结算' : '待结算' }}</ElTag></div><div class="settlement-grid"><div><span>结算基数 · 剩余实付</span><strong>{{ money(settlementBase) }}</strong></div><div><span>平台提点快照</span><strong>{{ order.shareRate }}%</strong></div><div><span>预计平台服务费</span><strong>{{ money(platformFee) }}</strong></div><div><span>售后期</span><strong>{{ order.afterSaleDays }} 个自然日</strong></div><div><span>售后期截止</span><strong>{{ dateText(order.afterSaleEnd) }}</strong></div><div><span>结算条件</span><strong>售后期结束且无未完成退款</strong></div></div><p class="context-note">部分退款会调减结算基数；退款关单后如有剩余实付，按关单后的售后期结算。</p><div class="pane-actions"><ElButton @click="router.push('/wallet')">查看我的钱包</ElButton><ElButton @click="router.push({ path: '/review', query: { order: order.id } })">{{ order.status === 'completed' ? '查看或评价客户' : '查看评价' }}</ElButton></div></section>

      <section v-else class="detail-panel"><div class="section-title"><span class="section-icon"><ClipboardList :size="17" /></span><h2>服务详情</h2></div><div class="service-facts"><div><span>服务名称</span><strong>{{ order.serviceName }}</strong></div><div><span>服务分类</span><strong>{{ order.category || '—' }}</strong></div><div><span>服务规格</span><strong>{{ spec?.name || '—' }}</strong></div><div><span>付款与验收方式</span><strong>一次性付款 · 一次性验收</strong></div><div><span>服务开始规则</span><strong>{{ order.deliverySnapshot || (spec ? `支付后 ${spec.startDays} ${spec.dayType}开始` : '—') }}</strong></div><div><span>交付周期</span><strong>{{ spec?.deliveryDays ? `${spec.deliveryDays} 天` : '—' }}</strong></div><div><span>交付标准</span><strong>{{ spec?.standard || '—' }}</strong></div><div><span>客户原始需求</span><strong>{{ order.customerRequest || '—' }}</strong></div><div><span>需求附件</span><strong>{{ order.requestAttachments?.join('、') || '—' }}</strong></div></div><p class="context-note">订单交易规则以下单快照为准。旧订单如缺少下单快照字段，以现有订单数据展示；演示订单未提供客户需求和附件。</p></section>
    </main>
    <aside class="order-aside"><h2>订单信息</h2><div class="aside-pairs"><div><span>来源园区</span><strong>{{ parkName }}</strong></div><div><span>客户</span><strong>{{ order.customer }}</strong></div><div><span>服务分类</span><strong>{{ order.category || '—' }}</strong></div><div><span>服务规格</span><strong>{{ spec?.name || '—' }}</strong></div><div><span>交付周期</span><strong>{{ spec?.deliveryDays ? `${spec.deliveryDays} 天` : '—' }}</strong></div><div><span>数量</span><strong>{{ order.quantity || 1 }} {{ spec?.unit || '项' }}</strong></div></div><div class="aside-amounts"><div><span>订单总金额</span><strong>{{ money(order.amount) }}</strong></div><div><span>已付金额</span><strong>{{ money(order.paid) }}</strong></div><div><span>待付金额</span><strong>{{ money(Math.max(0, order.amount - order.paid)) }}</strong></div><div v-if="order.refunded"><span>已退款</span><strong>{{ money(order.refunded) }}</strong></div></div><ElButton class="contact-button" @click="contactOpen = true"><MessageCircle :size="15" />联系客户</ElButton></aside></div><ElDialog v-model="contactOpen" title="联系客户" width="420px"><div class="contact-dialog"><div><span>客户</span><strong>{{ order.customer }}</strong></div><div><span>来源园区</span><strong>{{ parkName }}</strong></div><p>此演示订单未同步联系人及联系方式，请从实际订单接口获取后联系客户。</p></div><template #footer><ElButton @click="contactOpen = false">关闭</ElButton></template></ElDialog>
  </div>
  <div v-else class="biz-page biz-empty"><h3>订单不存在</h3><ElButton @click="router.push('/order')">返回订单管理</ElButton></div>
